import sys

def solve():
    # Read all input from stdin
    # Using sys.stdin.read().split() handles input robustly regardless of line breaks
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    n = int(input_data[0])
    k = int(input_data[1])
    s = input_data[2]

    ans = 0
    current_len = 0

    # Iterate through the string to find contiguous segments of 'O'
    for char in s:
        if char == 'O':
            current_len += 1
        else:
            if current_len >= k:
                ans += current_len // k
            current_len = 0

    # Check if there is a remaining segment after the last character
    if current_len >= k:
        ans += current_len // k

    print(ans)

