class Solution:
    def numberOfSubstrings(self, s: str, k: int) -> int:
        n = len(s)
        total = n * (n + 1) // 2
        invalid = 0

        for i in range(n):
            char_count = {}
            j = i
            while j < n:
                char_count[s[j]] = char_count.get(s[j], 0) + 1

                # If any character appears >= k times, this substring is valid
                if any(v >= k for v in char_count.values()):
                    break

                j += 1

        return total - invalid

from typing import List

class Solution:
    def maxScore(self, n: int, k: int, stayScore: List[List[int]], travelScore: List[List[int]]) -> int:
        # Initialize dp array for day 0
        # dp[j] represents the max points ending at city j after day 0
        dp = [stayScore[0][j] for j in range(n)]

        # Iterate through days from 1 to k-1
        for i in range(1, k):
            new_dp = [0] * n
            # First, compute the "Stay" option for each city j
            # If we stay at city j, we add stayScore[i][j] to the max points from day i-1 at city j
            for j in range(n):
                stay_val = dp[j] + stayScore[i][j]
                new_dp[j] = stay_val

            # Now, iterate over all possible previous cities m to find the max "Move" option
            # If we move from city m to city j, we add travelScore[m][j] to the max points from day i-1 at city m
            for m in range(n):
                prev_max = dp[m]
                # Update new_dp[j] for all j
                for j in range(n):
                    move_val = prev_max + travelScore[m][j]
                    if move_val > new_dp[j]:
                        new_dp[j] = move_val

            dp = new_dp

        return max(dp)

class Solution:
    def shiftDistance(self, s: str, t: str, nextCost: List[int], previousCost: List[int]) -> int:
        import sys
        sys.setrecursionlimit(2000) # Not needed but safe

        # Prefix sums calculation
        # next_cost_prefix[i] = sum(nextCost[0]...nextCost[i])
        next_cost_prefix = [0] * 26
        for i in range(26):
            if i == 0:
                next_cost_prefix[i] = nextCost[i]
            else:
                next_cost_prefix[i] = next_cost_prefix[i-1] + nextCost[i]

        # prev_cost_prefix[i] = sum(previousCost[0]...previousCost[i])
        prev_cost_prefix = [0] * 26
        for i in range(26):
            if i == 0:
                prev_cost_prefix[i] = previousCost[i]
            else:
                prev_cost_prefix[i] = prev_cost_prefix[i-1] + previousCost[i]

        total_shift = 0

        for i in range(len(s)):
            u = ord(s[i]) - ord('a')
            v = ord(t[i]) - ord('a')

            if u == v:
                continue

            # Forward cost (u -> v clockwise)
            # Path indices: u, u+1, ..., v-1
            # Number of steps = (v - u + 26) % 26
            forward_cost = 0
            steps = (v - u + 26) % 26
            if steps > 0:
                if u < v:
                    # Range [u, v-1]
                    # Sum = P[v-1] - P[u-1]
                    if u == 0:
                        forward_cost = next_cost_prefix[v-1]
                    else:
                        forward_cost = next_cost_prefix[v-1] - next_cost_prefix[u-1]
                else:
                    # Range [u, 25] + [0, v-1]
                    # Sum = (P[25] - P[u-1]) + P[v-1]
                    if u == 0:
                        forward_cost = next_cost_prefix[25]
                    else:
                        forward_cost = (next_cost_prefix[25] - next_cost_prefix[u-1]) + next_cost_prefix[v-1]

            # Backward cost (u -> v counter-clockwise)
            # Path indices: u, u-1, ..., v+1
            # This is range [v+1, u]
            backward_cost = 0
            if u > v:
                # Range [v+1, u]
                # Sum = P[u] - P[v]
                backward_cost = prev_cost_prefix[u] - prev_cost_prefix[v]
            else:
                # Range [v+1, 25] + [0, u]
                # Sum = (P[25] - P[v]) + P[u]
                backward_cost = (prev_cost_prefix[25] - prev_cost_prefix[v]) + prev_cost_prefix[u]

            total_shift += min(forward_cost, backward_cost)

        return total_shift

